L1: #!/usr/bin/env node
L2: // Sync the release version across the three places it lives, then let the
L3: // caller rebuild the bundle. Invoked by
L4: // @semantic-release/exec (prepareCmd):  node scripts/sync-version.mjs <version>
L5: //
L6: // The version is duplicated in package.json, src/version.ts (the value the
L7: // bundle embeds) and SKILL.md frontmatter; semantic-release computes it from the
L8: // Conventional Commits, so this keeps all three in lockstep. CHANGELOG.md is
L9: // owned by @semantic-release/changelog, which writes the generated release
L10: // notes before @semantic-release/git commits the bump — so it is NOT touched here.
L11: import { readFileSync, writeFileSync } from "node:fs";
L12: 
L13: const version = process.argv[2];
L14: if (!version || !/^\d+\.\d+\.\d+(?:-[\w.]+)?$/.test(version)) {
L15:   console.error(`sync-version: expected a semver version, got "${version ?? ""}"`);
L16:   process.exit(1);
L17: }
L18: 
L19: function edit(path, transform) {
L20:   const before = readFileSync(path, "utf8");
L21:   const after = transform(before);
L22:   if (after === before) {
L23:     console.error(`sync-version: WARNING — no change applied to ${path}`);
L24:   }
L25:   writeFileSync(path, after);
L26: }
L27: 
L28: // package.json — the top-level "version" field.
L29: edit("package.json", (s) => s.replace(/("version":\s*")[^"]+(")/, `$1${version}$2`));

