async function cmdOrchestrate(values: Record<string, string>, bools: ReadonlySet<string>): Promise<number> {
  if (!values.run) throw new UsageError("orchestrate needs --run <dir>");
  const runDir = resolveRun(values.run);
  // The emitted scripts bake in the absolute engine path: an installed skill
  // runs far from the user's project, and a subagent handed a relative path
  // resolves it against its own cwd.
  const engineAbs = fileURLToPath(new URL(import.meta.url));
  if (isTenderRun(runDir)) return tenderOrchestrateCmd(runDir, engineAbs, values, bools, IO);

  const result = emitOrchestration(runDir, engineAbs, {
    phase: values.phase,
    eco: bools.has("eco"),
    countryCode: requireManifest(runDir).target.countryCode,
  });

  if (bools.has("list") || bools.has("json")) {
    out(
      jsonLine({
        run: runDir,
        exitCode: result.exitCode,
        phases: result.phases.map((p) => ({ name: p.name, ready: p.ready, items: p.items, prerequisite: p.prerequisite })),
      }),
    );
  } else {
    for (const file of result.written) out(file);
    if (result.exitCode === 0) {
      // The host-neutral route first; the Workflow scripts are a Claude Code extra.
      const orch = join(runDir, "orchestration");
      say(`next: dispatch one subagent per batch with ${join(orch, "agents", "<role>.md")} (batches in ${join(orch, "RUNBOOK.md")}),`);
      say("      or work down RUNBOOK.md yourself (the --eco path).");
      if (result.written.some((f) => f.endsWith(".workflow.mjs"))) {
        say("      optional — Claude Code: launch <phase>.workflow.mjs with the Workflow tool for one-call parallel fan-out.");
      }
    }
  }
  for (const notice of result.notices) say(`  ${notice}`);
  for (const error of result.errors) say(`  ${error}`);
  return result.exitCode;
}

export async function main(argv: readonly string[]): Promise<number> {
  brandEngine();
  const parsed = parseArgs(argv, SPEC);
  if (parsed.kind === "help") {
    out(HELP);
    return EXIT_OK;
  }
  if (parsed.kind === "version") {
    out(VERSION);
    return EXIT_OK;
  }

  const { command, values, bools } = parsed;
  if (bools.has("stdout") || process.env.ULTRAPROSPECT_NO_WRITE === "1") setNoWrite(true);
  const text = positionalText(parsed);

  switch (command) {
    case "ingest":
      return cmdIngest(values, bools);
    case "where":
      return cmdWhere(values, bools, text);
    case "scan":
      return cmdScan(values, bools, text);
    case "match":
      return cmdMatch(values, bools);
    case "confirm":
      return cmdConfirm(values, bools);
    case "resolve":
      return cmdResolve(values, bools);
    case "enrich":
      return cmdEnrich(values, bools);
    case "score":
      return cmdScore(values, bools);
    case "feedback":
      return cmdFeedback(values);
    case "dossier":
      return cmdDossier(values, bools);
    case "check":
      return cmdCheck(values, bools);
    case "render":
      return cmdRender(values, bools);
    case "watch":
      return cmdWatch(values, bools);
    case "orchestrate":
      return cmdOrchestrate(values, bools);
    case "tenders":
      return cmdTenders(values, bools, IO, DEFAULT_OUT);
    case "tender":
      return cmdTender(values, bools, IO);
    case "bid":
      return cmdBid(values, bools, IO);
    case "awards":
      return cmdAwards(values, bools, IO, DEFAULT_OUT);
    case "mcp":
      return cmdMcp(values);
    case "doctor":
      // `--country` narrows the register probes to the ones that serve it, and
      // the keys go WITH the probe: a diagnostic handed a credential must use
      // it, not report the connector as skipped for want of it.
      return runDoctor({ json: bools.has("json"), out, say }, values.country, connectorKeys(values));
    case "version":
      out(VERSION);
      return EXIT_OK;
    default:
      throw new UsageError(`unknown command "${command}"`);
  }
}

/**
 * Whether the file node was asked to run IS this module, whatever it is called.
 *
 * `isInvokedDirectly` recognises the entry by its file name, so a copy of the
 * bundle saved as `prospect.mjs` imported fine and ran nothing: exit 0, no
 * output, no error. Comparing real paths names the module itself, and still
 * answers false to anything that merely imports it — the skill-bundle drift
 * gate reads the flag tables that way, and so do the tests. Real paths on both
 * sides, because `npm i -g` runs the bin through a symlink.
 */
export function isProcessEntry(argv1: string | undefined, moduleUrl: string): boolean {
  if (!argv1) return false;
  try {
    return realpathSync(argv1) === realpathSync(fileURLToPath(moduleUrl));
  } catch {
    // `node -e`, a deleted script, a non-file URL: not this module being run.
    return false;
  }
}

if (isProcessEntry(process.argv[1], import.meta.url) || isInvokedDirectly(process.argv[1], "ultraprospect")) {
  main(process.argv.slice(2))
    .then((code) => {
      process.exitCode = code;
    })
    .catch((e: any) => {
      if (!e?.handled) process.stderr.write(`ultraprospect: ${e?.message ?? e}\n`);
      process.exitCode = typeof e?.exitCode === "number" ? e.exitCode : EXIT_FAILURE;
    });
}

// Which activity vocabulary a country speaks, and how to read a code in it.
//
// `src/render.ts` already models the hard part of this: the register files a
// company under an activity code and OSM tags a shopfront by feature key, and a
// table listing "shop 460 / G 128" side by side reads as one ranking of one
// thing when it is neither. Going multi-country adds a third and a fourth
// vocabulary, so the rule gets stated once, here:
//
//   A SECTION IS NEVER CARRIED WITHOUT ITS SCHEME.
//
// NACE and US SIC both label their top level A, B, C… and they disagree about
// what those letters mean. `place.category` was already namespaced
// (`"naf=62.01Z"`), which is the seam this module formalises.

import { NACE_SECTION_LABELS, NACE_SECTIONS, naceSection } from "./nace.js";
import { US_SIC_LABELS, US_SIC_SECTIONS, usSicDivision } from "./us-sic.js";

/** The vocabularies in play. `none` is honest, not a failure: some registers publish no activity code at all. */
export type ActivityScheme = "nace" | "us-sic" | "none";

export interface ActivityVocabulary {
  scheme: ActivityScheme;
  /** How the scheme names its top level, for help text and error messages. */
  sectionTerm: string;
  /** Every valid section value, in nomenclature order. Empty for `none`. */
  sections: readonly string[];
  /** The section a full code belongs to, or undefined if the code is malformed. */
  sectionOf(code: string): string | undefined;
  /** Plain words for a section, or the raw value when the scheme has no label for it. */
  label(section: string): string;
}

const NACE_VOCABULARY: ActivityVocabulary = {
  scheme: "nace",
  sectionTerm: "NACE section letter",
  sections: NACE_SECTIONS,
  sectionOf: naceSection,
  label: (s) => NACE_SECTION_LABELS[s] ?? s,
};

const US_SIC_VOCABULARY: ActivityVocabulary = {
  scheme: "us-sic",
  sectionTerm: "US SIC division letter",
  sections: US_SIC_SECTIONS,
  sectionOf: usSicDivision,
  label: (s) => US_SIC_LABELS[s] ?? s,
};

const NO_VOCABULARY: ActivityVocabulary = {
  scheme: "none",
  sectionTerm: "activity section",
  sections: [],
  sectionOf: () => undefined,
  label: (s) => s,
};

export const VOCABULARIES: Record<ActivityScheme, ActivityVocabulary> = {
  nace: NACE_VOCABULARY,
  "us-sic": US_SIC_VOCABULARY,
  none: NO_VOCABULARY,
};

/** The vocabulary a scheme name denotes. Unknown names get `none` rather than a throw. */
export function vocabularyOf(scheme: ActivityScheme | undefined): ActivityVocabulary {
  return VOCABULARIES[scheme ?? "none"] ?? NO_VOCABULARY;
}

/**
 * Read a namespaced category back into its parts.
 *
 * `"naf=62.01Z"` -> `{ prefix: "naf", code: "62.01Z" }`, `"shop=bakery"` ->
 * `{ prefix: "shop", code: "bakery" }`. An unprefixed string is not a code in
 * any scheme, so it comes back with no prefix rather than being guessed at.
 */
export function splitCategory(category: string | undefined): { prefix?: string; code?: string } {
  if (!category) return {};
  const at = category.indexOf("=");
  if (at < 0) return { code: category };
  return { prefix: category.slice(0, at), code: category.slice(at + 1) };
}

/**
 * Validate `--section` values against the vocabulary that will actually receive them.
 *
 * Returns the values that are valid plus the ones that are not, rather than
 * throwing on the first bad one: a user who typed `--section J,Zz,M` should be
 * told about `Zz` and still get J and M, and a user who aimed a NACE letter at a
 * US run should be told THAT rather than handed an empty result set.
 */
export function partitionSections(sections: readonly string[], vocabulary: ActivityVocabulary): { valid: string[]; unknown: string[] } {
  if (vocabulary.scheme === "none") return { valid: [], unknown: [...sections] };
  const allowed = new Set(vocabulary.sections);
  const valid: string[] = [];
  const unknown: string[] = [];
  for (const raw of sections) {
    const s = raw.trim().toUpperCase();
    if (!s) continue;
    if (allowed.has(s)) valid.push(s);
    else unknown.push(raw);
  }
  return { valid, unknown };
}

export { NACE_SECTIONS, NACE_SECTION_LABELS, naceSection } from "./nace.js";
export { US_SIC_SECTIONS, US_SIC_LABELS, usSicDivision } from "./us-sic.js";

// The connector table, and the only place that decides which register runs where.
//
// Before this file the answer lived in one line of `scan.ts`:
//
//     const registerApplies = target.countryCode === "fr";
//
// which was accurate and unextendable. Now a country's register support is a row
// in `CONNECTORS`, and FIVE separate things read that same row: the sweep lane,
// the confirm pass, `doctor`'s probes, `manifest.licences`, and the weekly
// canary. That is the point. The alternative — a list here, a switch in doctor,
// a hardcoded count in the eval workflow — is the drift `engine-repin.yml`
// already warns about: "the automation cannot drift from the list it is supposed
// to be watching."
//
// Adding a country is one import and one array entry.
import { czAres } from "./cz-ares.js";
import { euVies } from "./eu-vies.js";
import { fiPrh } from "./fi-prh.js";
import { frSirene } from "./fr-sirene.js";
import { deOffeneRegister } from "./de-offeneregister.js";
import { eeAriregister } from "./ee-ariregister.js";
import { gbCompaniesHouse } from "./gb-companies-house.js";
import { gleif } from "./gleif.js";
import { noBrreg } from "./no-brreg.js";
import { plKrs } from "./pl-krs.js";
import { usEdgar } from "./us-edgar.js";
import type { Availability, ConnectorContext, RegistryConnector, RegistryRecord } from "./types.js";

/**
 * Every connector, in the order they should be TRIED.
 *
 * Order is behaviour, not presentation: `connectorsFor` returns `confirm` in
 * this order and `confirm` takes the first answer. National registers come
 * first because they are authoritative for their own country and hold the whole
 * economy; the cross-border authorities come last because each knows strictly
 * less. VIES says a VAT number is live and, for about half the member states,
 * nothing else. GLEIF knows every country and only the ~2.7 million entities
 * that hold an LEI.
 *
 * Adding a country is one import and one entry. Nothing else in the tree needs
 * to hear about it: the sweep lane, `confirm`, `doctor`, `manifest.licences`
 * and the weekly canary all read this array.
 */
export const CONNECTORS: readonly RegistryConnector[] = [
  // National registers, authoritative for their own country.
  frSirene,
  gbCompaniesHouse,
  // Before VIES on purpose. For Germany the two answer different questions and
  // this one answers the harder half: VIES confirms a VAT number is live TODAY and
  // refuses to name its holder, while this names who filed under an HRB number in
  // 2017-2019. An identity, even a dated one, beats an anonymous confirmation.
  deOffeneRegister,
  eeAriregister,
  noBrreg,
  fiPrh,
  czAres,
  plKrs,
  usEdgar,
  // Cross-border authorities. Broad reach, narrow answers.
  euVies,
  gleif,
];

export function connectorById(id: string): RegistryConnector | undefined {
  return CONNECTORS.find((c) => c.id === id);
}

/** Does this connector serve this country? `["*"]` means everywhere. */
export function servesCountry(connector: RegistryConnector, countryCode: string | undefined): boolean {
  if (connector.countries.includes("*")) return true;
  if (!countryCode) return false;
  return connector.countries.includes(countryCode.toLowerCase());
}

export interface ConnectorSelection {
  /** The one connector that can enumerate this territory, if any. */
  sweep?: RegistryConnector;
  /** Connectors that can confirm a company found by another lane, best first. */
  confirm: RegistryConnector[];
  /** Connectors that serve the country but cannot run — no key, typically. Never silently dropped. */
  unavailable: Array<{ connector: RegistryConnector; availability: Availability }>;
}

export interface SelectOptions {
  /** Restrict to these connector ids. An id that serves no country here is reported, not ignored. */
  only?: string[];
  ctx?: ConnectorContext;
}

/**
 * Which connectors apply to a country, split by what they can actually do.
 *
 * A connector that declares no `sweep` is NOT a degraded sweep connector. It is
 * a different kind of answer, and the caller has to treat it as one — which is
 * why they come back in separate fields rather than as one list the caller has
 * to introspect.
 */
export function connectorsFor(countryCode: string | undefined, opts: SelectOptions = {}): ConnectorSelection {
  const ctx = opts.ctx ?? {};
  const only = opts.only?.length ? new Set(opts.only.map((s) => s.trim().toLowerCase()).filter(Boolean)) : undefined;

  const selection: ConnectorSelection = { confirm: [], unavailable: [] };
  for (const connector of CONNECTORS) {
    if (only && !only.has(connector.id)) continue;
    if (!servesCountry(connector, countryCode)) continue;

    const availability = connector.availability(ctx);
    if (!availability.available) {
      selection.unavailable.push({ connector, availability });
      continue;
    }
    if (connector.sweep && !selection.sweep) selection.sweep = connector;
    if (connector.lookup || connector.verifyId) selection.confirm.push(connector);
  }
  return selection;
}

/** Connector ids named in `--registry` that match no connector at all. A typo must not read as "no register here". */
export function unknownConnectorIds(only: readonly string[] | undefined): string[] {
  if (!only?.length) return [];
  const known = new Set(CONNECTORS.map((c) => c.id));
  return only.map((s) => s.trim().toLowerCase()).filter((s) => s && !known.has(s));
}

/**
 * The sentence the manifest and the report use when a country has no sweep.
 *
 * Deliberately not "unavailable" and not an error. Outside France no public
 * register can be swept without a key; that is a property of the world, and
 * saying it plainly is the difference between an honest run and one that reads
 * like a failure.
 */
export function noSweepReason(countryCode: string | undefined, selection: ConnectorSelection): string {
  const where = countryCode ? `country=${countryCode}` : "country unknown";
  if (selection.confirm.length) {
    const names = selection.confirm.map((c) => c.id).join(", ");
    return `no register can be swept for ${where}; OSM covered the territory and ${names} can confirm each company (run \`confirm\`)`;
  }
  if (selection.unavailable.length) {
    const blocked = selection.unavailable
      .map(({ connector, availability }) => `${connector.id} (${availability.available ? "" : availability.reason})`)
      .join(", ");
    return `no register ran for ${where}: ${blocked}`;
  }
  return `no register connector covers ${where}; the territory is OSM-only and the list is not a register extract`;
}

/**
 * The register's own words for a headcount band.
 *
 * A band code is meaningless without the connector that issued it: "12" is
 * 20-49 employees in France and nothing at all in Norway. So the lookup goes
 * through the connector, and an unknown code comes back as itself rather than
 * as a confident mistranslation.
 */
export function sizeBandLabel(record: Pick<RegistryRecord, "connectorId">, band: string | undefined): string | undefined {
  if (!band) return undefined;
  const bands = connectorById(record.connectorId)?.sizeBands;
  return bands?.find((b) => b.code === band)?.label ?? band;
}

/**
 * The smallest headcount a record is consistent with, or undefined when unknown.
 *
 * An exact number beats a band, and a band that means "undetermined" is not
 * evidence of zero employees — it is evidence of nothing, and must not let a
 * `--min-employees` filter through.
 */
export function employeeFloor(record: Pick<RegistryRecord, "connectorId" | "employees" | "sizeBand" | "parent">): number | undefined {
  if (typeof record.employees === "number") return record.employees;
  const bands = connectorById(record.connectorId)?.sizeBands;
  if (!bands) return undefined;
  const code = record.parent?.sizeBand ?? record.sizeBand;
  const floor = bands.find((b) => b.code === code)?.floor;
  return typeof floor === "number" && floor >= 0 ? floor : undefined;
}

